132	beforeAll(async ({}, suite) => {
133	  testPath = suite.file.filepath!
134	  testName = slash(testPath).match(/playground\/([\w-]+)\//)?.[1]
135	  testDir = path.dirname(testPath)
136	  if (testName) {
137	    testDir = path.resolve(workspaceRoot, 'playground-temp', testName)
138	  }
139	
140	  // skip browser setup for hmr-ssr playground
141	  if (testName === 'hmr-ssr') {
142	    return
143	  }
144	
145	  const wsEndpoint = inject('wsEndpoint')
146	  if (!wsEndpoint) {
147	    throw new Error('wsEndpoint not found')
148	  }
149	
150	  browser = await chromium.connect(wsEndpoint)
151	  page = await browser.newPage()
152	
153	  try {
154	    page.on('console', (msg) => {
155	      // ignore favicon request in headed browser
156	      if (
157	        process.env.VITE_DEBUG_SERVE &&
158	        msg.text().includes('Failed to load resource:') &&
159	        msg.location().url.includes('favicon.ico')
160	      ) {
161	        return
162	      }
163	      browserLogs.push(msg.text())
164	    })
165	    page.on('pageerror', (error) => {
166	      browserErrors.push(error)
167	    })
168	
169	    // if this is a test placed under playground/xxx/__tests__
170	    // start a vite server in that directory.
171	    if (testName) {
172	      // when `root` dir is present, use it as vite's root
173	      const testCustomRoot = path.resolve(testDir, 'root')
174	      rootDir = fs.existsSync(testCustomRoot) ? testCustomRoot : testDir
175	
176	      // separate rootDir for variant
177	      const variantName = path.basename(path.dirname(testPath))
178	      if (variantName !== '__tests__') {
179	        const variantTestDir = testDir + '__' + variantName
180	        if (fs.existsSync(variantTestDir)) {
181	          rootDir = testDir = variantTestDir
182	        }
183	      }
184	
185	      const testCustomServe = [
186	        path.resolve(path.dirname(testPath), 'serve.ts'),
187	        path.resolve(path.dirname(testPath), 'serve.js'),
188	      ].find((i) => fs.existsSync(i))
189	
190	      if (testCustomServe) {
191	        // test has custom server configuration.
192	        const mod = await import(testCustomServe)
193	        const serve = mod.serve || mod.default?.serve
194	        const preServe = mod.preServe || mod.default?.preServe
195	        if (preServe) {
196	          await preServe()
197	        }
198	        if (serve) {
199	          server = await serve()
200	          viteServer = mod.viteServer
201	        }
202	      } else {
203	        await startDefaultServe()
204	      }
205	    }
206	  } catch (e) {
207	    // Closing the page since an error in the setup, for example a runtime error
